-- One-time repair of seven pre-existing production ACL differences from the v12 source.
-- This restores existing source grants; no function body, migration ledger, run or bundle changes.
-- Exact before-state rejects a second execution. Run inside the reviewed paused rollout transaction.
do $acl_reconcile$
declare v jsonb; r text; target regprocedure; definitions jsonb := '[{"signature":"qorpera_acquire_native_provider_connection_lease(uuid,uuid,text,uuid,text,integer)","sha256":"4e5f733ac0149e9ac7b874c7dc0cd09d0c865e92b41360eb180c77d077e88f3c","before":{"anon":true,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false}},{"signature":"qorpera_company_context_source(qorpera_execution_runs,text,uuid)","sha256":"d1df3dffaa601708cf3af62abac4885ebeee1847184fa518758ccb8670867bad","before":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_company_path_plan_digest(jsonb,jsonb)","sha256":"e5330658b9aab9770e26399f98287156e6fad9756f585008cf837960e95b6419","before":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_consent_provider_connection_autonomous(uuid,uuid,boolean)","sha256":"ad8b3b4c89bf5e0037bd1f0c8506db018f7f8f8bae013327e5fe9c7e1f33113a","before":{"anon":false,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":true,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_create_member_execution_sponsor(uuid,uuid,uuid,bigint,boolean)","sha256":"c8b90a2771990473202c60fd9cc7f1cea1e6367af06fa3b056a266ce1a9d3d15","before":{"anon":true,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":true,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_describe_company_run_context(jsonb)","sha256":"4b7214fea024cd8a69296de0ee6175802dc2c90894035a38711488e0111fe339","before":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false}},{"signature":"qorpera_execution_sponsor_available(qorpera_execution_runs)","sha256":"5dee5dc5fad12a04b53d3e4dfebec7afdb2bd506824700534f159ed9e8bc45ea","before":{"anon":true,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_handoff_run_sponsor(uuid,text)","sha256":"dd99a2492d548cafe8e3eaa1f65f6953591058a4713a482c1458eea23191fba4","before":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false}},{"signature":"qorpera_materialize_wake_execution_runs(integer)","sha256":"fbfad063da7c51424aea3af33b0ef299c08c490f130e04342248e066a7f9be90","before":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false}},{"signature":"qorpera_provider_autonomous_authority(uuid,bigint)","sha256":"121f70a624f99aa9558e74e4460ca1b60e217772c041bcf94794428ec42928d0","before":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_read_company_run_context(jsonb,text,uuid,text,integer,integer)","sha256":"b5524ce7dcbb5c5d073408910ba233d0a1723189927d335f09d68ef74bc9d446","before":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false}},{"signature":"qorpera_release_native_provider_connection_lease(uuid,uuid,text,uuid,text,text)","sha256":"82186e65ae0078e93613ff23be92a9aee5c928452ddfa522cf60de364075ce96","before":{"anon":true,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":true,"qorpera_secret_broker":false}},{"signature":"qorpera_reserve_execution_sponsor_authority(uuid)","sha256":"fdafae3c4e19fcc23c8e18e4cef578a0eadee6a61ec53d1ebe67cb20a2a04135","before":{"anon":true,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_run_autonomous_authority(qorpera_execution_runs)","sha256":"de84726326cc7cdc37c174fa20d22231e5f6cd9f348ffd3e3a2b9f10853df990","before":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_run_continuation(qorpera_execution_runs)","sha256":"ae9aa4ab3186f9af235095ca502eac1e81dfb2c9911c58545e0a8f85dde1b034","before":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}},{"signature":"qorpera_runner_broker_locked_job(uuid,text,uuid,text)","sha256":"dd565b29460564ee6c40ab5a24d1c9c7796b5e0d39aadc95f21699623a8dca68","before":{"anon":true,"authenticated":true,"service_role":true,"qorpera_secret_broker":false},"after":{"anon":false,"authenticated":false,"service_role":false,"qorpera_secret_broker":false}}]'::jsonb;
begin
 for v in select * from jsonb_array_elements(definitions) loop
  target := ('public.'||(v->>'signature'))::regprocedure;
  if encode(extensions.digest(pg_get_functiondef(target),'sha256'),'hex') <> v->>'sha256'
   or (select pg_get_userbyid(proowner) from pg_proc where oid=target) <> 'postgres' then raise exception 'Runtime definition differs'; end if;
  for r in select jsonb_object_keys(v->'before') loop
   if has_function_privilege(r,target,'execute') <> (v->'before'->>r)::boolean then raise exception 'Runtime privilege prestate differs'; end if;
  end loop;
 end loop;
 for v in select * from jsonb_array_elements(definitions) where value->'before' <> value->'after' loop
  target := ('public.'||(v->>'signature'))::regprocedure;
  execute format('revoke execute on function %s from public,anon,authenticated,service_role,qorpera_secret_broker',target);
  for r in select jsonb_object_keys(v->'after') loop
   if (v->'after'->>r)::boolean then execute format('grant execute on function %s to %I',target,r); end if;
  end loop;
 end loop;
 for v in select * from jsonb_array_elements(definitions) loop
  target := ('public.'||(v->>'signature'))::regprocedure;
  if encode(extensions.digest(pg_get_functiondef(target),'sha256'),'hex') <> v->>'sha256' then raise exception 'Runtime body changed'; end if;
  for r in select jsonb_object_keys(v->'after') loop
   if has_function_privilege(r,target,'execute') <> (v->'after'->>r)::boolean then raise exception 'Runtime privilege poststate differs'; end if;
  end loop;
 end loop;
end $acl_reconcile$;
